<?php
require_once __DIR__.'/app/bootstrap.php';require_auth();if((string)setting('leaderboard_enabled','1')!=='1'){flash('error','The leaderboard is currently disabled by the platform administrator.');redirect('dashboard.php');}$leaders=Learning::leaderboard(50);$user=current_user();$currentRank=null;foreach($leaders as $i=>$leader){if((int)$leader['id']===(int)$user['id'])$currentRank=$i+1;}
$pageTitle='Leaderboard';$bodyClass='leaderboard-page';require base_path('partials/header.php');
