<section class="workspace-section page-intro"><div><span class="eyebrow">Learning community</span><h1>Leaderboard</h1><p>Rankings reward completed learning and original projects. Scores are generated from persisted learner activity.</p></div><?php if($currentRank): ?><div class="rank-pill"><span>Your rank</span><strong>#<?= $currentRank ?></strong></div><?php endif; ?></section>
<?php if($leaders): ?><section class="podium"><?php foreach(array_slice($leaders,0,3) as $index=>$leader): ?><article class="podium-place place-<?= $index+1 ?>"><span class="podium-rank"><?= $index+1 ?></span><span class="avatar large"><?= e(initials($leader['name'])) ?></span><h2><?= e($leader['name']) ?></h2><small><?= e($leader['school_name']) ?></small><strong><?= number_format((int)$leader['points']) ?> pts</strong></article><?php endforeach; ?></section><section class="panel leaderboard-table"><div class="table-header"><span>Rank</span><span>Learner</span><span>Lessons</span><span>Projects</span><span>Points</span></div><?php foreach($leaders as $index=>$leader): ?><div class="leader-row <?= (int)$leader['id']===(int)$user['id']?'current-user':'' ?>"><strong class="leader-rank">#<?= $index+1 ?></strong><span class="leader-person"><span class="avatar small"><?= e(initials($leader['name'])) ?></span><span><strong><?= e($leader['name']) ?><?= (int)$leader['id']===(int)$user['id']?' (You)':'' ?></strong><small><?= e($leader['school_name']) ?></small></span></span><span data-label="Lessons"><?= (int)$leader['completed_lessons'] ?></span><span data-label="Projects"><?= (int)$leader['project_count'] ?></span><strong data-label="Points"><?= number_format((int)$leader['points']) ?></strong></div><?php endforeach; ?></section><?php else: ?><section class="panel empty-panel large"><span class="empty-icon"><?= icon('trophy') ?></span><h2>The leaderboard is ready</h2><p>Learners appear after accounts are created and learning activity earns points.</p></section><?php endif; ?>
